select 'cust' k, (select jsonb_agg(jsonb_build_object('id',id,'ref',agency_ref,'name',name,'hh',hh,'base',base,'food',food,'active',active,'phone',phone,'apt',apt))::text from customers where regexp_replace(coalesce(phone,''),'\D','','g') like '%3474713863%' or regexp_replace(coalesce(cell,''),'\D','','g') like '%3474713863%') v
union all select 'reqs', (select jsonb_agg(jsonb_build_object('wk',cr.effective_week,'st',cr.status,'p',cr.payload,'at',cr.requested_at) order by cr.requested_at desc)::text from change_requests cr join customers c on c.id=cr.customer_id where regexp_replace(coalesce(c.phone,''),'\D','','g') like '%3474713863%' or regexp_replace(coalesce(c.cell,''),'\D','','g') like '%3474713863%');
